teacher:
function teach(state) {
  if (!state) return 'NOOP';
  // 1. Game over -> JUMP restarts
  if (state.over === true) return 'JUMP';
  var p = state.player || {}, t = state.threat;
  // 2. In the air
  if (p.air === true) {
    if (!t) return 'NOOP';
    // hold JUMP while the dino is still going up (full-height jump)
    if (p.rising === true) return t.duckable === true ? 'NOOP' : 'JUMP';
    if (t.duckable === true) return 'NOOP';
    // back on the ground before the press lands: a fresh jump from the ground
    if (p.landsBeforeInput === true) return (t.jumpTiming === 'ok' || t.jumpTiming === 'late') ? 'JUMP' : 'NOOP';
    // past the top: fast drop when it is safe and lands sooner
    if (p.dropSafe === true) return 'DUCK';
    return 'NOOP';
  }
  // 3. No threat -> NOOP
  if (!t) return 'NOOP';
  // 4. Bird at head height -> DUCK once it is near
  if (t.duckable === true) return t.contact === 'far' ? 'NOOP' : 'DUCK';
  // 5. Jump timing ok or late -> JUMP
  if (t.jumpTiming === 'ok' || t.jumpTiming === 'late') return 'JUMP';
  // 6. Otherwise (early) -> wait
  return 'NOOP';
}
